from pathlib import Path
import json
from urllib.request import Request, urlopen
from skydiscover.optimize.evaluation.evaluation_result import EvaluationResult
URL = '<VERIFIER>/evaluate'
FAILED = {'full_score': -2.0, 'combined_score': -2.0, 'stage': 0.0}


def _call(program_path, scope):
    try:
        source = Path(program_path).read_text(encoding='utf-8')
        payload = json.dumps({'source': source, 'scope': scope}).encode('utf-8')
        req = Request(URL, payload, {'Content-Type': 'application/json'})
        with urlopen(req, timeout=870) as response:
            out = json.load(response)
        metrics = {k: float(v) for k, v in out['metrics'].items()}
        return EvaluationResult(metrics=metrics, artifacts={k: str(v) for k, v in out['artifacts'].items()})
    except Exception as exc:
        return EvaluationResult(metrics=dict(FAILED), artifacts={
            'feedback': 'evaluation failed: %s: %s' % (type(exc).__name__, str(exc)[:300])})


def evaluate_stage1(program_path):
    return _call(program_path, 'screen')


def evaluate_stage2(program_path):
    return _call(program_path, 'full')


def evaluate(program_path):
    return evaluate_stage2(program_path)
